"""R284GH exact two-heavy coverage for q >= 4u-1. Stdlib only.
Keep R284GG_exact_general_u_certificate.py alongside this file.
"""
import R284GG_exact_general_u_certificate as gg
import base64,zlib,json,hashlib
DATA=""""""
if __name__=='__main__':
    raw=zlib.decompress(base64.b64decode(DATA))
    assert hashlib.sha256(raw).hexdigest()=='d07f329fad0c969b0fa5622f27056cf67eee8637601b71b2e1d2e79315bd603f'
    data=json.loads(raw)
    base=list(gg.base)
    base[1]=(gg.row([],-1,4),1)
    counts=[]
    for nh in gg.combinations((3,5,6),2):
        a=base+[(gg.row([p],-2,-2),-1) for p in nh]
        count=gg.checktree(a,tuple(range(6)),data[''.join(map(str,nh))])
        counts.append(count)
        print(nh,count)
    assert counts==[165,167,165]
    print('Exact coverage verified:',sum(counts))
